#!/usr/bin/env bash
# Sweep the k-probe across the available multirelational fixtures and
# produce a single CSV aggregating all observed cardinalities.
#
# Inputs: benchmark/fixtures/multirelational/*.txt (generated by
#   generate_fixtures.py and small_map_study/generate_study_fixtures.py)
# Output: benchmark/small_map_study/k_probe_all.csv
#
# One row per (workload, map_name, log2 bucket) tuple. Assumes the probe
# binary has been built (cmake with -DVCP_BUILD_K_PROBE=ON).

set -euo pipefail

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
FIX="$ROOT/benchmark/fixtures"
OUT_DIR="$ROOT/benchmark/small_map_study/results"
PROBE="$ROOT/build-probe/benchmark/small_map_study/k_probe_tool"

if [ ! -x "$PROBE" ]; then
    echo "probe binary missing: $PROBE" >&2
    echo "build it with:" >&2
    echo "  cmake -S . -B build-probe -DCMAKE_BUILD_TYPE=Release " \
         "-DVCP_BUILD_BENCHMARKS=ON -DVCP_BUILD_K_PROBE=ON" >&2
    echo "  cmake --build build-probe --target k_probe_tool -j" >&2
    exit 2
fi

mkdir -p "$OUT_DIR"
AGG="$OUT_DIR/k_probe_all.csv"
: > "$AGG"

run_one() {
    local label="$1"; local r="$2"; local d="$3"; local graph="$4"; local pairs="$5"
    local tmp="$OUT_DIR/k_probe_${label}.csv"
    echo ">> probing $label (r=$r, d=$d)" >&2
    VCP_K_PROBE_OUTPUT="$tmp" "$PROBE" --workload "$label" \
        -r "$r" -d "$d" --graph "$graph" --pairs "$pairs" 2>&1 | sed 's/^/   /'
    # Append non-header rows to the aggregate, preserving the header only
    # once at the top.
    if [ ! -s "$AGG" ]; then
        head -1 "$tmp" > "$AGG"
    fi
    tail -n +2 "$tmp" >> "$AGG"
}

# --- r=2 undirected (existing fixtures, full 2-bit saturation) ---
run_one "r2_u_n100_p030" 2 0 \
    "$FIX/multirelational/er_n100_p0.30_s42.txt" \
    "$FIX/pairs/mr_er_n100_p0.30_s42.pairs"
run_one "r2_u_n200_p015" 2 0 \
    "$FIX/multirelational/er_n200_p0.15_s42.txt" \
    "$FIX/pairs/mr_er_n200_p0.15_s42.pairs"

# --- r=2 directed (existing fixtures reinterpreted) ---
# The r=2 multirelational fixtures are symmetric, so they can be read as
# bidirectional-directed graphs without regenerating. This exercises
# vcp<4, 2, true>.
run_one "r2_d_n100_p030" 2 1 \
    "$FIX/multirelational/er_n100_p0.30_s42.txt" \
    "$FIX/pairs/mr_er_n100_p0.30_s42.pairs"
run_one "r2_d_n200_p015" 2 1 \
    "$FIX/multirelational/er_n200_p0.15_s42.txt" \
    "$FIX/pairs/mr_er_n200_p0.15_s42.pairs"

# --- r=30, values spanning 4 bits (moderate diversity) ---
run_one "r30_u_div4_n100" 30 0 \
    "$FIX/multirelational/mr_r30_div4_n100_p0.30_s42.txt" \
    "$FIX/pairs/mr_mr_r30_div4_n100_p0.30_s42.pairs"
run_one "r30_u_div4_n200" 30 0 \
    "$FIX/multirelational/mr_r30_div4_n200_p0.15_s42.txt" \
    "$FIX/pairs/mr_mr_r30_div4_n200_p0.15_s42.pairs"

run_one "r30_d_div4_n100" 30 1 \
    "$FIX/multirelational/mr_r30_div4_n100_p0.30_s42_dsym.txt" \
    "$FIX/pairs/mr_mr_r30_div4_n100_p0.30_s42.pairs"
run_one "r30_d_div4_n200" 30 1 \
    "$FIX/multirelational/mr_r30_div4_n200_p0.15_s42_dsym.txt" \
    "$FIX/pairs/mr_mr_r30_div4_n200_p0.15_s42.pairs"

# --- r=30, full 30-bit range (high-diversity stress) ---
run_one "r30_u_full_n100" 30 0 \
    "$FIX/multirelational/mr_r30_full_n100_p0.30_s42.txt" \
    "$FIX/pairs/mr_mr_r30_full_n100_p0.30_s42.pairs"
run_one "r30_u_full_n200" 30 0 \
    "$FIX/multirelational/mr_r30_full_n200_p0.15_s42.txt" \
    "$FIX/pairs/mr_mr_r30_full_n200_p0.15_s42.pairs"

run_one "r30_d_full_n100" 30 1 \
    "$FIX/multirelational/mr_r30_full_n100_p0.30_s42_dsym.txt" \
    "$FIX/pairs/mr_mr_r30_full_n100_p0.30_s42.pairs"
run_one "r30_d_full_n200" 30 1 \
    "$FIX/multirelational/mr_r30_full_n200_p0.15_s42_dsym.txt" \
    "$FIX/pairs/mr_mr_r30_full_n200_p0.15_s42.pairs"

# --- Hub fixtures (v3_count spike stress) ---
run_one "r30_u_div4_hub_n200" 30 0 \
    "$FIX/multirelational/mr_r30_div4_hub_n200_s42.txt" \
    "$FIX/pairs/mr_mr_r30_div4_hub_n200_s42.pairs"
run_one "r30_d_div4_hub_n200" 30 1 \
    "$FIX/multirelational/mr_r30_div4_hub_n200_s42_dsym.txt" \
    "$FIX/pairs/mr_mr_r30_div4_hub_n200_s42.pairs"

run_one "r30_u_full_hub_n200" 30 0 \
    "$FIX/multirelational/mr_r30_full_hub_n200_s42.txt" \
    "$FIX/pairs/mr_mr_r30_full_hub_n200_s42.pairs"
run_one "r30_d_full_hub_n200" 30 1 \
    "$FIX/multirelational/mr_r30_full_hub_n200_s42_dsym.txt" \
    "$FIX/pairs/mr_mr_r30_full_hub_n200_s42.pairs"

echo "=== Aggregate: $AGG ==="
wc -l "$AGG"
